/**
 * Status of the external app
 */
declare const AppStatus: {
    readonly Active: "active";
    readonly Inactive: "inactive";
    readonly Error: "error";
};
type AppStatus = (typeof AppStatus)[keyof typeof AppStatus];

declare const ComponentType: {
    readonly Menu: "menu";
    readonly Panel: "panel";
};
type ComponentType = (typeof ComponentType)[keyof typeof ComponentType];

interface ComponentMetadata {
    id: string;
    type: ComponentType;
    /**
     * Optional pre-built lazy component (React.lazy() result).
     *
     * When provided, the host renders this component directly without loading it
     * via Module Federation `container.get()`. This allows plugins to expose only
     * `'./AppConfig'` in their webpack config — no per-component `exposes` entry needed.
     *
     * Example (in your AppConfig file):
     *
     *   import { lazy } from 'react'
     *   components: [{
     *     id: 'MyPanel',
     *     type: ComponentType.Panel,
     *     component: lazy(() => import('./components/MyPanel')),
     *   }]
     *
     * If omitted, the host falls back to loading the component via Module Federation
     * using the `id` as the module name (legacy behaviour, requires a matching
     * `exposes` entry in the plugin's webpack.config.js).
     */
    component?: any;
}

/**
 * Base interface to define the app object
 *
 * All apps should implement this and this will be the entry point for the app
 *
 */
interface CyApp {
    id: string;
    name: string;
    description?: string;
    /**
     * Semantic version of the app (e.g. '1.2.0').
     *
     * Recommended: import from the app's own package.json so this value
     * stays in sync with the published npm version automatically:
     *
     *   import packageJson from '../package.json'
     *   const { version } = packageJson        // destructure to avoid webpack warning
     *   export const MyApp: CyApp = { ..., version }
     *
     * Requires `resolveJsonModule: true` in tsconfig.json
     * (already enabled in all example apps).
     */
    version?: string;
    /**
     * Name of components to be exposed via Module Federation.
     * @deprecated Prefer `resources` (declarative) or runtime registration via mount().
     */
    components?: ComponentMetadata[];
    status?: AppStatus;
}

/**
 * Identifies a specific host-managed UI location that plugins can occupy.
 *
 * Current slots (first rollout):
 *   'right-panel'  — tabbed side panel on the right
 *   'apps-menu'    — dropdown in the Apps toolbar button
 *
 * Reserved for future rollouts:
 *   'left-panel', 'bottom-panel', 'tools-menu', 'status-bar', 'modal-launcher'
 */
type ResourceSlot = 'right-panel' | 'apps-menu';
/** Props injected by the host into every 'right-panel' component. */
interface PanelHostProps {
}
/**
 * Props injected by the host into every 'apps-menu' component.
 *
 * When `closeOnAction: true` on the registration, the host wraps the
 * component in a click-capturing container that auto-closes the dropdown
 * via `queueMicrotask`. Plugins do NOT need to call `handleClose` in
 * that case — it is still injected for edge cases.
 *
 * When `closeOnAction: false` (default), the plugin MUST call
 * `handleClose` manually when appropriate.
 */
interface MenuItemHostProps {
    handleClose: () => void;
}
interface RegisterPanelOptions {
    id: string;
    /** Display label for the panel tab. Falls back to `id` if omitted. */
    title?: string;
    order?: number;
    group?: string;
    requires?: {
        /** true → resource is hidden unless a network is currently loaded */
        network?: boolean;
        /** true → resource is hidden unless at least one element is selected */
        selection?: boolean;
    };
    component: React.ComponentType<PanelHostProps>;
    /**
     * Custom fallback component rendered when this panel throws a render error.
     * If omitted, the host's default PluginFallback is used.
     */
    errorFallback?: React.ComponentType<{
        error: Error;
        resetErrorBoundary: () => void;
    }>;
}
interface RegisterMenuItemOptions {
    id: string;
    /** Display label for the menu item. Falls back to `id` if omitted. */
    title?: string;
    order?: number;
    group?: string;
    requires?: {
        network?: boolean;
        selection?: boolean;
    };
    component: React.ComponentType<MenuItemHostProps>;
    /**
     * If true, the host automatically closes the Apps dropdown after the menu
     * item component's onClick handler completes.
     * @default false
     */
    closeOnAction?: boolean;
    /** Custom error fallback (same as RegisterPanelOptions.errorFallback). */
    errorFallback?: React.ComponentType<{
        error: Error;
        resetErrorBoundary: () => void;
    }>;
}
/** Entry for batch registration via registerAll(). */
interface RegisterResourceEntry {
    slot: ResourceSlot;
    id: string;
    title?: string;
    order?: number;
    group?: string;
    requires?: {
        network?: boolean;
        selection?: boolean;
    };
    component: React.ComponentType<any>;
    /** Custom error fallback. */
    errorFallback?: React.ComponentType<{
        error: Error;
        resetErrorBoundary: () => void;
    }>;
    /** For 'apps-menu' only: auto-close after action. */
    closeOnAction?: boolean;
}
/** Returned by getRegisteredResources(). */
interface RegisteredResourceInfo {
    resourceId: string;
    slot: ResourceSlot;
    id: string;
    title?: string;
    order?: number;
    requires?: {
        network?: boolean;
        selection?: boolean;
    };
}
/** Returned by getResourceVisibility(). */
interface ResourceVisibilityResult {
    registered: boolean;
    visible: boolean;
    hiddenReason?: 'app-inactive' | 'requires-network' | 'requires-selection' | 'slot-not-rendered';
}
/**
 * Declarative resource entry used in CyAppWithLifecycle.resources.
 * Same fields as RegisterResourceEntry — the host registers these
 * automatically when the app is loaded.
 */
interface ResourceDeclaration {
    slot: ResourceSlot;
    id: string;
    title?: string;
    order?: number;
    group?: string;
    requires?: {
        network?: boolean;
        selection?: boolean;
    };
    component: React.ComponentType<any>;
    errorFallback?: React.ComponentType<{
        error: Error;
        resetErrorBoundary: () => void;
    }>;
    closeOnAction?: boolean;
}
/**
 * Per-app resource registration API.
 *
 * Each instance is bound to a specific appId at creation time
 * (via `createResourceApi(appId)`). This prevents apps from
 * registering resources under another app's identity.
 *
 * Available via `AppContext.apis.resource` in `mount()` or
 * `useAppContext().apis.resource` in plugin components.
 * NOT available on `window.CyWebApi`.
 */
interface ResourceApi {
    /**
     * Returns the set of UI slots this host version supports.
     * Apps should register resources only for supported slots.
     */
    getSupportedSlots(): ResourceSlot[];
    /**
     * Register a panel in the 'right-panel' slot. Uses upsert semantics:
     * if a panel with the same `id` is already registered by this app,
     * it is replaced in place (preserving tab selection).
     */
    registerPanel(options: RegisterPanelOptions): ApiResult<{
        resourceId: string;
    }>;
    unregisterPanel(panelId: string): ApiResult;
    /**
     * Register a menu item in the 'apps-menu' slot. Uses upsert semantics.
     */
    registerMenuItem(options: RegisterMenuItemOptions): ApiResult<{
        resourceId: string;
    }>;
    unregisterMenuItem(menuItemId: string): ApiResult;
    unregisterAll(): ApiResult;
    /**
     * Register multiple resources in a single call. Uses upsert semantics
     * per entry. Entries that fail validation are skipped (logged) but do
     * not block other entries.
     *
     * Always returns `ok()` — check `result.data.errors.length > 0` to
     * detect partial failures.
     */
    registerAll(entries: RegisterResourceEntry[]): ApiResult<{
        registered: Array<{
            resourceId: string;
        }>;
        errors: Array<{
            id: string;
            slot: ResourceSlot;
            error: ApiError;
        }>;
    }>;
    /**
     * Returns all resources registered by this app.
     */
    getRegisteredResources(): RegisteredResourceInfo[];
    /**
     * Returns the visibility evaluation result for a resource registered
     * by this app. The `id` parameter is the slot-local id passed to
     * `registerPanel` / `registerMenuItem`.
     */
    getResourceVisibility(id: string): ResourceVisibilityResult;
}

/**
 * Per-app API object passed to mount(). Extends CyWebApiType and adds
 * `resource` and per-app `contextMenu` as required fields — the host
 * always injects them before calling mount().
 *
 * Intentionally distinct from CyWebApiType:
 *   CyWebApiType   = window.CyWebApi shape — no `resource` (window-safe)
 *   AppContextApis = AppContext.apis shape — `resource` required (mount-safe)
 */
interface AppContextApis extends CyWebApiType {
    /** Per-app resource registration API. Always provided by the host. */
    readonly resource: ResourceApi;
    /**
     * Per-app context menu API (factory-bound to this app's ID).
     * Items registered here are auto-cleaned when the app is disabled.
     * Overrides the anonymous contextMenu from CyWebApiType.
     */
    readonly contextMenu: ContextMenuApi;
}
/**
 * Context object passed to external apps during mount().
 *
 * Provides pre-instantiated, per-app API instances. The host creates
 * a unique AppContextApis object for each app — it is NOT the same as
 * window.CyWebApi (which has no `resource` field and uses the anonymous
 * contextMenu singleton).
 */
interface AppContext {
    /** The unique ID of this app instance */
    readonly appId: string;
    /**
     * Per-app API instances. Includes all domain APIs from CyWebApiType
     * plus `resource` (ResourceApi) and a per-app `contextMenu` factory.
     */
    readonly apis: AppContextApis;
}
/**
 * Extended CyApp interface with lifecycle callbacks, declarative resource
 * registration, and API version declaration.
 *
 * Backward-compatible — existing apps without lifecycle methods or the
 * resources field continue to work unchanged.
 */
interface CyAppWithLifecycle extends CyApp {
    /**
     * Declared API version this app targets (e.g. '1.0').
     * The host may use this for compatibility checks in future releases.
     */
    apiVersion?: string;
    /**
     * Declarative resource registrations. The host registers these automatically
     * when the app is loaded — no mount() implementation needed. Resources
     * declared here follow the same slot model, visibility rules, and cleanup
     * semantics as runtime-registered resources.
     *
     * For dynamic registration (conditional, user-driven), use
     * apis.resource.registerPanel() from mount() instead.
     */
    resources?: ResourceDeclaration[];
    /**
     * Called when the app is activated (after React components are registered).
     * Receives an AppContext providing access to all app APIs.
     * If this returns a Promise, the host awaits it before marking
     * the app as ready.
     */
    mount?(context: AppContext): void | Promise<void>;
    /**
     * Called when the app is deactivated or unloaded.
     * Apps must clean up DOM nodes, listeners, timers, and async tasks.
     * No async work should survive past unmount().
     * Will always be called, even on page reload.
     */
    unmount?(): void | Promise<void>;
}

/**
 * Map of all typed events dispatched by Cytoscape Web.
 * Keys are the CustomEvent type strings; values are the event detail shapes.
 *
 * Vanilla JS consumers use `window.addEventListener` with these keys.
 * React consumers use the `useCyWebEvent` hook from `cyweb/EventBus`.
 *
 * When `@cytoscape-web/api-types` is added to tsconfig `types`, all
 * `window.addEventListener` overloads carry the correct detail type.
 */
interface CyWebEvents {
    /**
     * Fired once when the Cytoscape Web App API is fully initialized
     * and `window.CyWebApi` is ready to use. Subscribe to this event
     * before accessing `window.CyWebApi`.
     */
    'cywebapi:ready': Record<string, never>;
    /** Fired when a new network is added to the workspace. */
    'network:created': {
        networkId: IdType;
    };
    /** Fired when a network is removed from the workspace. */
    'network:deleted': {
        networkId: IdType;
    };
    /**
     * Fired when the active (current) network changes.
     * `previousId` is an empty string if no network was active before.
     */
    'network:switched': {
        networkId: IdType;
        previousId: IdType;
    };
    /** Fired when the selection state of the current network's view changes. */
    'selection:changed': {
        networkId: IdType;
        selectedNodes: IdType[];
        selectedEdges: IdType[];
    };
    /** Fired immediately before a layout algorithm begins executing. */
    'layout:started': {
        networkId: IdType;
        algorithm: string;
    };
    /** Fired when a layout algorithm has finished and node positions are updated. */
    'layout:completed': {
        networkId: IdType;
        algorithm: string;
    };
    /**
     * Fired when a visual style property changes on any network.
     * `property` is the `VisualPropertyName` string (e.g., `'NODE_BACKGROUND_COLOR'`).
     */
    'style:changed': {
        networkId: IdType;
        property: string;
    };
    /**
     * Fired when table data is written to a network's node or edge table.
     * `rowIds` is the set of node/edge IDs whose data changed in this write.
     */
    'data:changed': {
        networkId: IdType;
        tableType: 'node' | 'edge';
        rowIds: IdType[];
    };
}
/**
 * Mapped type used to augment `WindowEventMap`.
 * Maps each `CyWebEvents` key to a `CustomEvent` with the correct detail type
 * so that `window.addEventListener` overloads carry full type information.
 */
type CyWebEventMap = {
    [K in keyof CyWebEvents]: CustomEvent<CyWebEvents[K]>;
};

declare global {
    interface WindowEventMap extends CyWebEventMap {
    }
    interface Window {
        /**
         * The Cytoscape Web App API, available after `cywebapi:ready` fires.
         *
         * @example
         * ```typescript
         * window.addEventListener('cywebapi:ready', () => {
         *   const api = window.CyWebApi  // typed as CyWebApiType
         *   const result = api.network.getCurrentNetwork()
         * })
         * ```
         */
        CyWebApi: CyWebApiType;
    }
}

